import{_ as a,o as t,c as n,a2 as i}from"./chunks/framework.CHeM0PsO.js";const p=JSON.parse('{"title":"ADR 0002 — One universal binary, not a build per instance","description":"","frontmatter":{"status":"Accepted","date":"2026-07-31T00:00:00.000Z","deciders":"kasunben","sourceUrl":"https://github.com/sovereignfs/sovereign-mobile/blob/main/docs/adrs/0002-universal-one-binary-distribution.md"},"headers":[],"relativePath":"apps/mobile/adrs/0002-universal-one-binary-distribution.md","filePath":"apps/mobile/adrs/0002-universal-one-binary-distribution.md"}'),s={name:"apps/mobile/adrs/0002-universal-one-binary-distribution.md"};function r(o,e,l,d,c,u){return t(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="adr-0002-—-one-universal-binary-not-a-build-per-instance" tabindex="-1">ADR 0002 — One universal binary, not a build per instance <a class="header-anchor" href="#adr-0002-—-one-universal-binary-not-a-build-per-instance" aria-label="Permalink to &quot;ADR 0002 — One universal binary, not a build per instance&quot;">​</a></h1><h2 id="status" tabindex="-1">Status <a class="header-anchor" href="#status" aria-label="Permalink to &quot;Status&quot;">​</a></h2><p>Accepted. Locked by sovereign workstream 0002&#39;s &quot;Decisions locked&quot; table.</p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>Sovereign is self-hosted: every user runs their own instance at their own URL. A native app that hardcodes a backend, or that requires each self-hoster to produce and sign their own store submission, does not scale to the product&#39;s actual user base and adds a distribution burden with no real benefit.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p>Ship <strong>one binary</strong> to the App Store and Play Store. On first launch the user enters their own instance URL; the shell validates and persists it. Any Sovereign instance works with the same published app — nothing is baked in at build time.</p><h2 id="rejected-alternatives" tabindex="-1">Rejected alternatives <a class="header-anchor" href="#rejected-alternatives" aria-label="Permalink to &quot;Rejected alternatives&quot;">​</a></h2><ul><li><strong>A build per instance.</strong> Each self-hoster would need to fork, configure, sign, and submit their own copy — an unreasonable burden that contradicts self-hosting&#39;s whole premise of &quot;run the software, not maintain a packaging pipeline.&quot;</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li>Never hardcode an instance URL anywhere outside tests.</li><li>First-launch onboarding and multi-instance switching are core, load-bearing features, not optional polish — see <a href="./../epics/shell.html">epics/shell.md</a>.</li><li>Instance identity/validation (sovereign epic task 20.2, a separate leg living in the <code>sovereign</code> monorepo, not here) is a prerequisite for this shell to distinguish a real Sovereign instance from any server that happens to return <code>200 OK</code>.</li></ul>',11)])])}const b=a(s,[["render",r]]);export{p as __pageData,b as default};
